#!/usr/bin/env python3
from pathlib import Path
import re, sys

root=Path(sys.argv[1] if len(sys.argv)>1 else "game")
runtime=root/"scripts"/"art"/"d2d29_minimal_token_runtime.gd"
if not runtime.exists():
    raise SystemExit("D2D.68 requires D2D.62 runtime")

s=runtime.read_text(encoding="utf-8")
if 'title.text = "D2D.62 FEMALE PROPORTION FIX:"' not in s:
    raise SystemExit("D2D.68 baseline title anchor missing")

# Exact supplied female head image bytes.
head="[... ELLIPSIZATION ...]"
if len(head) < 1000:
    raise SystemExit("D2D.68 female head data too short")

lines=s.splitlines()
hits=0
for i,line in enumerate(lines):
    if line.startswith("const FEMALE_HEAD_B64 :="):
        lines[i]='const FEMALE_HEAD_B64 := "'+head+'"'
        hits+=1
if hits!=1:
    raise SystemExit(f"D2D.68 expected one female head constant, found {hits}")
s="\n".join(lines)+("\n" if s.endswith("\n") else "")

# Force final bare-head draw to pick female texture in female mode.
pat=r'draw_texture_rect\(tex_head_right,\s*(Rect2\([^\n]+\)),\s*false\)'
count=len(re.findall(pat,s))
if count<1:
    raise SystemExit("D2D.68 no male bare-head draw found")
s=re.sub(pat,lambda m:
    'draw_texture_rect((tex_head_female if female_mode and tex_head_female != null else tex_head_right), '+m.group(1)+', false)',
    s)

s=s.replace('title.text = "D2D.62 FEMALE PROPORTION FIX:"',
            'title.text = "D2D.68 EXACT FEMALE HEAD:"',1)

# Verify final runtime actually contains the exact head bytes and no unconditional male head draw.
if ('const FEMALE_HEAD_B64 := "'+head+'"') not in s:
    raise SystemExit("D2D.68 exact female head bytes missing after patch")
if len(re.findall(r'draw_texture_rect\(tex_head_right,',s))!=0:
    raise SystemExit("D2D.68 unconditional male head draw remains")
if 'tex_head_female = _texture_from_embedded_png(FEMALE_HEAD_B64)' not in s:
    raise SystemExit("D2D.68 female head loader missing")
runtime.write_text(s,encoding="utf-8")

ep=root/"export_presets.cfg"
e=ep.read_text(encoding="utf-8")
e,n1=re.subn(r'(?m)^version/code=\d+$','version/code=141',e,count=1)
e,n2=re.subn(r'(?m)^version/name="[^"]*"$','version/name="0.21.0D2D.68"',e,count=1)
if n1!=1 or n2!=1: raise SystemExit("D2D.68 version anchors missing")
ep.write_text(e,encoding="utf-8")

sm=root/"scripts/save/save_manager.gd"
if sm.exists():
    t=sm.read_text(encoding="utf-8")
    t=re.sub(r'const GAME_VERSION := "[^"]+"','const GAME_VERSION := "0.21.0D2D.68"',t,count=1)
    sm.write_text(t,encoding="utf-8")

print("Applied D2D.68 exact female head + forced final female bare-head draw.")
